function visibleMenu(nodes, role) {
  if (!Array.isArray(nodes)) {
    throw new TypeError('nodes must be an array');
  }
  if (typeof role !== 'string') {
    throw new TypeError('role must be a string');
  }
  if (role.length === 0) {
    throw new RangeError('role must be non-empty');
  }

  const ids = new Set();
  function validate(list) {
    for (const node of list) {
      if (node === null || typeof node !== 'object' || Array.isArray(node) ||
          typeof node.id !== 'string' || !Array.isArray(node.roles) ||
          !Array.isArray(node.children)) {
        throw new TypeError('invalid node');
      }
      if (node.id.length === 0 || node.roles.length === 0) {
        throw new RangeError('empty node field');
      }
      if (ids.has(node.id)) {
        throw new RangeError('duplicate id');
      }
      ids.add(node.id);
      for (const allowed of node.roles) {
        if (typeof allowed !== 'string') {
          throw new TypeError('roles must contain strings');
        }
        if (allowed.length === 0) {
          throw new RangeError('roles must be non-empty');
        }
      }
      validate(node.children);
    }
  }
  validate(nodes);

  function copyVisible(list) {
    const result = [];
    for (const node of list) {
      if (node.roles.includes(role)) {
        result.push({
          id: node.id,
          roles: [...node.roles],
          children: copyVisible(node.children)
        });
      }
    }
    return result;
  }
  return copyVisible(nodes);
}

module.exports = { visibleMenu };
```

