const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['visibleMenu']);
const { visibleMenu } = api;

assert.deepEqual(visibleMenu([], 'admin'), []);

const nodes = [
  {
    id: 'home',
    roles: ['*'],
    children: [
      { id: 'dashboard', roles: ['admin'], children: [] },
      { id: 'profile', roles: ['user', 'admin'], children: [] }
    ]
  },
  {
    id: 'hidden-parent',
    roles: ['user'],
    children: [
      { id: 'hidden-admin-child', roles: ['admin'], children: [] }
    ]
  },
  { id: 'settings', roles: ['admin'], children: [] }
];
const snapshot = JSON.parse(JSON.stringify(nodes));
const result = visibleMenu(nodes, 'admin');
assert.deepEqual(result, [
  {
    id: 'home',
    roles: ['*'],
    children: [
      { id: 'dashboard', roles: ['admin'], children: [] },
      { id: 'profile', roles: ['user', 'admin'], children: [] }
    ]
  },
  { id: 'settings', roles: ['admin'], children: [] }
]);
assert.deepEqual(nodes, snapshot);
assert.notStrictEqual(result, nodes);
assert.notStrictEqual(result[0], nodes[0]);
assert.notStrictEqual(result[0].roles, nodes[0].roles);
assert.notStrictEqual(result[0].children, nodes[0].children);
assert.notStrictEqual(result[0].children[0], nodes[0].children[0]);
assert.notStrictEqual(result[0].children[0].roles, nodes[0].children[0].roles);
assert.notStrictEqual(result[0].children[0].children, nodes[0].children[0].children);
result[0].roles.push('changed');
result[0].children[0].id = 'changed';
assert.deepEqual(nodes, snapshot);

const again = visibleMenu(nodes, 'admin');
assert.notStrictEqual(again[0], result[0]);
assert.notStrictEqual(again[0].roles, result[0].roles);

assert.throws(() => visibleMenu(null, 'admin'), TypeError);
assert.throws(() => visibleMenu([], 1), TypeError);
assert.throws(() => visibleMenu([], ''), RangeError);
assert.throws(() => visibleMenu([null], 'admin'), TypeError);
assert.throws(() => visibleMenu([{ id: 1, roles: ['admin'], children: [] }], 'admin'), TypeError);
assert.throws(() => visibleMenu([{ id: '', roles: ['admin'], children: [] }], 'admin'), RangeError);
assert.throws(() => visibleMenu([{ id: 'x', roles: [], children: [] }], 'admin'), RangeError);
assert.throws(() => visibleMenu([{ id: 'x', roles: [1], children: [] }], 'admin'), TypeError);
assert.throws(() => visibleMenu([{ id: 'x', roles: [''], children: [] }], 'admin'), RangeError);
assert.throws(() => visibleMenu([{ id: 'x', roles: ['admin'], children: null }], 'admin'), TypeError);
assert.throws(() => visibleMenu([
  { id: 'same', roles: ['user'], children: [
    { id: 'same', roles: ['admin'], children: [] }
  ] }
], 'admin'), RangeError);

// Invalid descendants must be validated even below a hidden parent.
assert.throws(() => visibleMenu([
  { id: 'hidden', roles: ['user'], children: [
    { id: '', roles: ['admin'], children: [] }
  ] }
], 'admin'), RangeError);

